    adcs_quat_t qe, qt, qc;
    double s, angle;
    if ((estimated == NULL) || (target == NULL) || (error == NULL))
        return ADCS_E_NULL;
    error->x = 0.0;
    error->y = 0.0;
    error->z = 0.0;
    if (!isfinite(estimated->w) || !isfinite(estimated->x) ||
        !isfinite(estimated->y) || !isfinite(estimated->z) ||
        !isfinite(target->w) || !isfinite(target->x) ||
        !isfinite(target->y) || !isfinite(target->z))
        return ADCS_E_DEGENERATE;
    if (adcs_quat_normalize(estimated, &qe) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    if (adcs_quat_normalize(target, &qt) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    qc = adcs_quat_conjugate(&qe);
    qe = adcs_quat_multiply(&qt, &qc);
    if (qe.w < 0.0) {
        qe.w = -qe.w;
        qe.x = -qe.x;
        qe.y = -qe.y;
        qe.z = -qe.z;
    }
    s = sqrt(qe.x * qe.x + qe.y * qe.y + qe.z * qe.z);
    if (s <= ADCS_EPS_NORM) {
        error->x = 2.0 * qe.x;
        error->y = 2.0 * qe.y;
        error->z = 2.0 * qe.z;
    } else {
        angle = 2.0 * atan2(s, qe.w);
        error->x = angle * qe.x / s;
        error->y = angle * qe.y / s;
        error->z = angle * qe.z / s;
    }
    return ADCS_OK;
}

