    adcs_quat_t qe, qt, qc, qerr;
    adcs_vec3_t v;
    double s, angle, k;

    if (error == NULL) {
        return ADCS_E_NULL;
    }
    error->x = 0.0;
    error->y = 0.0;
    error->z = 0.0;

    if ((estimated == NULL) || (target == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(estimated->w)) || (!isfinite(estimated->x)) ||
        (!isfinite(estimated->y)) || (!isfinite(estimated->z)) ||
        (!isfinite(target->w)) || (!isfinite(target->x)) ||
        (!isfinite(target->y)) || (!isfinite(target->z))) {
        return ADCS_E_DEGENERATE;
    }

    if ((adcs_quat_normalize(estimated, &qe) != ADCS_OK) ||
        (adcs_quat_normalize(target, &qt) != ADCS_OK)) {
        return ADCS_E_DEGENERATE;
    }

    qc = adcs_quat_conjugate(&qe);
    qerr = adcs_quat_multiply(&qt, &qc);

    if (qerr.w < 0.0) {
        qerr.w = -qerr.w;
        qerr.x = -qerr.x;
        qerr.y = -qerr.y;
        qerr.z = -qerr.z;
    }

    v.x = qerr.x;
    v.y = qerr.y;
    v.z = qerr.z;
    s = sqrt(v.x * v.x + v.y * v.y + v.z * v.z);

    if (s <= ADCS_EPS_NORM) {
        *error = adcs_vec3_scale(&v, 2.0);
    } else {
        angle = 2.0 * atan2(s, qerr.w);
        k = angle / s;
        *error = adcs_vec3_scale(&v, k);
    }

    return ADCS_OK;
}

